235	// A library value (numpy array, Decimal, ...): Rc<dyn Ext> is a pointer and a vtable, so the value is boxed
236	// once more behind a thin Rc, keeping V two words.
237	pub struct ExtRc(pub Rc<Box<dyn Ext>>);
238	impl ExtRc {
239	    #[inline]
240	    pub fn new<T: Ext + 'static>(x: T) -> ExtRc {
241	        ExtRc(Rc::new(Box::new(x)))
242	    }
243	    #[inline]
244	    pub fn from_box(b: Box<dyn Ext>) -> ExtRc {
245	        ExtRc(Rc::new(b))
246	    }
247	    #[inline]
248	    pub fn ptr_eq(a: &ExtRc, b: &ExtRc) -> bool {
249	        Rc::ptr_eq(&a.0, &b.0)
250	    }
251	    #[inline]
252	    pub fn as_ptr(a: &ExtRc) -> *const u8 {
253	        Rc::as_ptr(&a.0) as *const u8
254	    }
255	    #[inline]
256	    pub fn strong_count(a: &ExtRc) -> usize {
257	        Rc::strong_count(&a.0)
258	    }
